parameters.jsCode:
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const clientKey = headers['x-primetek-key'] || headers['x-api-key'] || headers['authorization'];
const expectedKey = $env.PRIMETEK_GATEWAY_API_KEY || 'primetek_sec_change_in_env';

// 1. Authenticate Request
if (!clientKey || clientKey !== expectedKey) {
  return [{
    json: {
      authenticated: false,
      error: 'Unauthorized: Invalid or missing x-primetek-key header',
      statusCode: 401
    }
  }];
}

// 2. Validate Required Order Data
const phone = body.phone || body.to;
const name = body.name || 'Valued Customer';
const summary = body.summary || 'Custom Software Package';
const total = body.total || 0;

if (!phone) {
  return [{
    json: {
      authenticated: false,
      error: 'Bad Request: Customer phone number is required',
      statusCode: 400
    }
  }];
}

const cleanPhone = String(phone).replace(/[^0-9]/g, '');

// 3. Format Brand Message for PRIMETEK Customers
const messageText =
  `Hi ${name}! 👋\n\n` +
  `Thank you for ordering with *PRIMETEK*! 🚀\n\n` +
  `📦 *Order Details:*\n${summary}\n\n` +
  `💰 *Total Amount:* ₹${total.toLocaleString('en-IN')}\n\n` +
  `Our engineering team has received your order and is reviewing your specifications. We will share the UPI payment & delivery instructions shortly.\n\n` +
  `_Need immediate assistance? Simply reply to this WhatsApp message anytime!_`;

return [{
  json: {
    authenticated: true,
    cleanPhone: cleanPhone,
    customerName: name,
    messageText: messageText,
    email: body.email || '',
    company: body.company || '',
    notes: body.notes || '',
    total: total,
    items: body.items || [],
    instance: $env.WA_INSTANCE_PRIMETEK || 'primetek_store',
    statusCode: 200
  }
}];

parameters.responseBody:
